# -*- coding: utf-8 -*-
# Beit Rishon: the review round's exact text fixes (S4-01..06, S4-19, S2-06, U-26, U-27, and what the wording pass left). Idempotent.
import io
def patch(path, pairs):
    p = '/home/claude/beit-rishon/src/' + path
    s = io.open(p, encoding='utf-8').read(); n = 0
    for fid, old, new, cnt in pairs:
        if new and new in s and old not in s: continue
        c = s.count(old)
        assert c == cnt, (path, fid, c, cnt)
        s = s.replace(old, new); n += 1
    io.open(p, 'w', encoding='utf-8').write(s); print(path, n)

